const CACHE_NAME="aura-money-cache-v2",ASSETS=["./","./index.html","./bundle.js","./manifest.json","./icons/icon-192.png","./icons/icon-512.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(e!==CACHE_NAME)return caches.delete(e)}))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{"GET"===e.request.method&&e.request.url.startsWith(self.location.origin)&&!e.request.url.includes("/api/")&&e.respondWith(caches.match(e.request).then(t=>t?(fetch(e.request).then(t=>{200===t.status&&caches.open(CACHE_NAME).then(s=>s.put(e.request,t))}).catch(()=>{}),t):fetch(e.request)))});